sap.ui.define([
  "sap/ui/core/Control",
  "sap/m/Label",
  "sap/m/Input"
], function (Control, Label, Input) {
  "use strict";

  return Control.extend("my.app.control.LabeledInput", {
    metadata: {
      properties: {
        label: { type: "string", defaultValue: "" },
        value: { type: "string", defaultValue: "" }
      },
      aggregations: {
        _label: { type: "sap.m.Label", multiple: false, visibility: "hidden" },
        _input: { type: "sap.m.Input", multiple: false, visibility: "hidden" }
      },
      events: {
        change: { parameters: { value: { type: "string" } } }
      }
    },

    init: function () {
      const input = new Input({
        change: function (event) {
          const value = event.getParameter("value");
          this.setProperty("value", value, true);
          this.fireChange({ value: value });
        }.bind(this)
      });
      this.setAggregation("_input", input);
      this.setAggregation("_label", new Label({ labelFor: input }));
    },

    onBeforeRendering: function () {
      this.getAggregation("_label").setText(this.getLabel());
      this.getAggregation("_input").setValue(this.getValue());
    },

    renderer: {
      apiVersion: 2,
      render: function (rm, control) {
        rm.openStart("div", control);
        rm.class("myAppLabeledInput");
        rm.openEnd();
        rm.renderControl(control.getAggregation("_label"));
        rm.renderControl(control.getAggregation("_input"));
        rm.close("div");
      }
    }
  });
});

import Control from "sap/ui/core/Control";
import RenderManager from "sap/ui/core/RenderManager";
import HBox from "sap/m/HBox";
import Input from "sap/m/Input";
import Button from "sap/m/Button";

/**
 * @namespace my.app.control
 */
export default class SearchBox extends Control {
  static readonly metadata = {
    properties: {
      value: { type: "string", defaultValue: "" },
      placeholder: { type: "string", defaultValue: "" }
    },
    aggregations: {
      _layout: { type: "sap.m.HBox", multiple: false, visibility: "hidden" }
    },
    events: {
      search: { parameters: { query: { type: "string" } } }
    }
  };

  private input: Input;

  public init(): void {
    this.input = new Input(this.getId() + "-input");
    const button = new Button({
      icon: "sap-icon://search",
      press: () => this.fireEvent("search", { query: this.input.getValue() })
    });
    this.setAggregation("_layout", new HBox({ items: [this.input, button] }));
  }

  // pass the public property values down to the inner control
  public setValue(value: string): this {
    this.setProperty("value", value);
    this.input.setValue(value);
    return this;
  }

  public setPlaceholder(text: string): this {
    this.setProperty("placeholder", text);
    this.input.setPlaceholder(text);
    return this;
  }

  static renderer = {
    apiVersion: 2,
    render(rm: RenderManager, control: SearchBox): void {
      rm.openStart("div", control);
      rm.class("myAppSearchBox");
      rm.openEnd();
      rm.renderControl(control.getAggregation("_layout") as HBox);   // children render themselves
      rm.close("div");
    }
  };
}

sap.ui.define([
  "sap/m/Input",
  "sap/m/InputRenderer"
], function (Input, InputRenderer) {
  "use strict";

  return Input.extend("my.app.control.UpperCaseInput", {
    metadata: {
      properties: {
        upperCase: { type: "boolean", defaultValue: true }
      }
    },

    setValue: function (value) {
      const newValue = this.getUpperCase() && value ? value.toUpperCase() : value;
      return Input.prototype.setValue.call(this, newValue);
    },

    renderer: InputRenderer // reuse the standard renderer unchanged
  });
});

import Button from "sap/m/Button";
import MessageBox from "sap/m/MessageBox";

/**
 * @namespace my.app.control
 */
export default class ConfirmButton extends Button {
  static readonly metadata = {
    properties: {
      confirmText: { type: "string", defaultValue: "Are you sure?" }
    }
  };

  // no renderer declared -> the Button renderer is inherited
  static renderer = "sap.m.ButtonRenderer";

  public firePress(params?: object): this {
    MessageBox.confirm(this.getProperty("confirmText") as string, {
      onClose: (action: string) => {
        if (action === MessageBox.Action.OK) {
          super.firePress(params);   // only now fire the real event
        }
      }
    });
    return this;
  }
}

import Control from "sap/ui/core/Control";
import RenderManager from "sap/ui/core/RenderManager";
import Icon from "sap/ui/core/Icon";

/**
 * @namespace my.app.control
 */
export default class StatusBadge extends Control {
  static readonly metadata = {
    properties: {
      text: { type: "string", group: "Data", defaultValue: "" },
      status: { type: "sap.ui.core.ValueState", group: "Appearance", defaultValue: "None" }
    },
    aggregations: {
      icon: { type: "sap.ui.core.Icon", multiple: false }
    },
    events: {
      press: { parameters: { status: { type: "string" } } }
    }
  };

  // ---- lifecycle ----
  public init(): void { /* create internal objects */ }
  public onAfterRendering(): void { /* DOM ready: attach third-party libs here */ }
  public exit(): void { /* clean up timers, listeners, third-party objects */ }

  // ---- behavior: browser events ----
  public onclick(): void {
    this.fireEvent("press", { status: this.getProperty("status") });
  }
  public onsapenter(): void {
    this.onclick();   // keyboard support
  }

  // ---- rendering ----
  static renderer = {
    apiVersion: 2,
    render(rm: RenderManager, control: StatusBadge): void {
      rm.openStart("div", control);                     // writes the control ID
      rm.class("myAppStatusBadge");
      rm.class("myAppStatusBadge--" + control.getProperty("status"));
      rm.attr("tabindex", "0");
      rm.accessibilityState(control, { role: "button" });
      rm.openEnd();
      const icon = control.getAggregation("icon") as Icon;
      if (icon) {
        rm.renderControl(icon);
      }
      rm.text(control.getProperty("text"));             // escaped automatically
      rm.close("div");
    }
  };
}

Control.extend("my.app.control.TagList", {
  metadata: {
