});

renderer: {
  apiVersion: 2,
  render: function (rm, control) {
    rm.openStart("div", control);                 // root element with the control's ID
    rm.class("myAppStatusBadge");
    rm.class("myAppStatusBadge" + control.getStatus());
    rm.attr("tabindex", "0");
