sap.ui.define([
  "sap/m/Input"
], function (Input) {
  "use strict";

  return Input.extend("my.app.control.PrefixInput", {
    metadata: {
      properties: { prefix: { type: "string", defaultValue: "" } }
    },
    renderer: {
      // no render(): UI5 extends the Input renderer and replaces only this hook.
      // prependInnerContent is a protected, empty hook of sap.m.InputBaseRenderer
      // that writes content before the inner <input> element.
      prependInnerContent: function (rm, control) {
        rm.openStart("span");
        rm.class("myAppInputPrefix");
        rm.openEnd();
        rm.text(control.getPrefix());
        rm.close("span");
      }
    }
  });
});

import Button from "sap/m/Button";
import ButtonRenderer from "sap/m/ButtonRenderer";
import Renderer from "sap/ui/core/Renderer";

// 1. Reuse as-is: same HTML as sap.m.Button
export class PlainButton extends Button {
  static renderer = ButtonRenderer;
}

// 2. Extend: override one hook, keep the rest
const SpecialButtonRenderer = Renderer.extend(ButtonRenderer);
SpecialButtonRenderer.apiVersion = 2;                 // not inherited!
SpecialButtonRenderer.renderButtonAttributes = function (rm, control) {
  ButtonRenderer.renderButtonAttributes.apply(this, arguments);
  rm.class("myAppSpecialButton");
};

export class SpecialButton extends Button {
  static renderer = SpecialButtonRenderer;
}

