sap.ui.define(["sap/ui/core/Control", "sap/ui/core/Lib"], function (Control, Lib) {
  "use strict";
  const bundle = Lib.getResourceBundleFor("my.lib");

  return Control.extend("my.lib.StatusBadge", {
    renderer: {
      apiVersion: 2,
      render: function (rm, control) {
        rm.openStart("div", control);
        rm.attr("title", bundle.getText("STATUS_BADGE_TOOLTIP"));
        rm.openEnd();
        rm.close("div");
      }
    }
  });
});
